import requests

url = "https://api.example.com/echo"

payload = {
    "text": "he said \"hi\"
line2	TAB",
    "note": "back\slash café"
}
headers = {
    "accept": "application/json",
    "content-type": "application/json"
}

response = requests.post(url, json=payload, headers=headers)

print(response.text)
